mapper.update:
UPDATE report_job SET status=#{status}, report_id=COALESCE(#{reportId,jdbcType=OTHER},report_id),

    started_at=#{at}
    completed_at=#{at}, failure_reason=#{failureReason}

WHERE id=#{jobId}

    AND status='QUEUED'
    AND status IN ('QUEUED','RUNNING')

AND (CAST(#{reportId,jdbcType=OTHER} AS uuid) IS NULL OR report_id IS NULL OR report_id=#{reportId,jdbcType=OTHER})
